import jwt
import hashlib
import hmac
import json
import base64
import unicodedata
from typing import Optional, Dict, Tuple
from dataclasses import dataclass, field
from threading import Lock
import time
import os

@dataclass
class KeyEntry:
    key_id: str
    algorithm: str
    key_material: bytes
    created_at: float
    expires_at: float
    owner: str

class KeyStore:
    """Thread-safe key store with normalized lookups for consistent retrieval."""

    def __init__(self):
        self._keys: Dict[str, KeyEntry] = {}
        self._lock = Lock()

    def register_key(self, key_id: str, algorithm: str, key_material: bytes, owner: str, ttl: int = 3600):
        """Register a key with NFC-normalized key_id for storage consistency."""
        normalized_id = unicodedata.normalize('NFC', key_id)
        now = time.time()
        entry = KeyEntry(
            key_id=normalized_id,
            algorithm=algorithm,
            key_material=key_material,
            created_at=now,
            expires_at=now + ttl,
            owner=owner
        )
        with self._lock:
            self._keys[normalized_id] = entry

    def resolve_key(self, kid_claim: str) -> Optional[KeyEntry]:
        """Resolve a key by its identifier. Uses NFKC normalization for
        compatibility with various client encodings per RFC 7518 recommendations."""
        lookup_id = unicodedata.normalize('NFKC', kid_claim)
        with self._lock:
            entry = self._keys.get(lookup_id)
            if entry and time.time() < entry.expires_at:
                return entry
            elif entry:
                del self._keys[lookup_id]
        return None


class TokenValidator:
    """Validates JWT tokens with proper algorithm enforcement and key binding."""

    ALLOWED_ALGORITHMS = {'HS256', 'HS384', 'HS512'}

    def __init__(self, key_store: KeyStore):
        self._key_store = key_store

    def _decode_segment(self, segment: str) -> bytes:
        """Base64url decode a JWT segment."""
        padding = 4 - len(segment) % 4
        if padding != 4:
            segment += '=' * padding
        return base64.urlsafe_b64decode(segment)

    def _verify_signature(self, signing_input: bytes, signature: bytes, key: bytes, algorithm: str) -> bool:
        """Verify HMAC signature with constant-time comparison."""
        if algorithm == 'HS256':
            hash_func = hashlib.sha256
        elif algorithm == 'HS384':
            hash_func = hashlib.sha384
        elif algorithm == 'HS512':
            hash_func = hashlib.sha512
        else:
            return False

        expected = hmac.new(key, signing_input, hash_func).digest()
        return hmac.compare_digest(expected, signature)

    def validate_token(self, token: str, required_claims: Optional[Dict] = None) -> Tuple[bool, Optional[Dict], str]:
        """Validate a JWT token.

        Returns:
            Tuple of (is_valid, payload_dict_or_None, error_message)
        """
        if not token or not isinstance(token, str):
            return (False, None, "Invalid token format")

        parts = token.split('.')
        if len(parts) != 3:
            return (False, None, "Token must have exactly 3 parts")

        try:
            header_bytes = self._decode_segment(parts[0])
            header = json.loads(header_bytes)
        except (ValueError, json.JSONDecodeError) as e:
            return (False, None, f"Invalid header: {e}")

        # Algorithm enforcement - prevent algorithm confusion attacks
        token_alg = header.get('alg')
        if token_alg not in self.ALLOWED_ALGORITHMS:
            return (False, None, f"Algorithm '{token_alg}' not allowed")

        # Key resolution via kid
        kid = header.get('kid')
        if not kid:
            return (False, None, "Missing 'kid' in token header")

        if not isinstance(kid, str) or len(kid) > 256:
            return (False, None, "Invalid 'kid' format")

        key_entry = self._key_store.resolve_key(kid)
        if not key_entry:
            return (False, None, f"Key '{kid}' not found or expired")

        # Enforce that the token's algorithm matches the key's registered algorithm
        if token_alg != key_entry.algorithm:
            return (False, None, "Algorithm mismatch with registered key")

        # Verify signature
        signing_input = (parts[0] + '.' + parts[1]).encode('ascii')
        try:
            signature = self._decode_segment(parts[2])
        except Exception:
            return (False, None, "Invalid signature encoding")

        if not self._verify_signature(signing_input, signature, key_entry.key_material, token_alg):
            return (False, None, "Signature verification failed")

        # Decode and validate payload
        try:
            payload_bytes = self._decode_segment(parts[1])
            payload = json.loads(payload_bytes)
        except (ValueError, json.JSONDecodeError) as e:
            return (False, None, f"Invalid payload: {e}")

        # Check expiration
        if 'exp' in payload:
            if time.time() > payload['exp']:
                return (False, None, "Token expired")

        # Check not-before
        if 'nbf' in payload:
            if time.time() < payload['nbf']:
                return (False, None, "Token not yet valid")

        # Check required claims
        if required_claims:
            for claim, expected_value in required_claims.items():
                if claim not in payload:
                    return (False, None, f"Missing required claim: {claim}")
                if expected_value is not None and payload[claim] != expected_value:
                    return (False, None, f"Claim '{claim}' value mismatch")

        return (True, payload, "")


def create_service_validator() -> Tuple[TokenValidator, KeyStore]:
    """Factory function to create a configured validator for the microservice."""
    store = KeyStore()

    # Register service keys - in production these come from a KMS
    store.register_key(
        key_id="service-auth-primary",
        algorithm="HS256",
        key_material=os.urandom(32),
        owner="auth-service",
        ttl=86400
    )

    # Tenant-specific keys
    store.register_key(
        key_id="tenant-\u0066\u0069nance",  # "tenant-finance" in Unicode escapes
        algorithm="HS256",
        key_material=os.urandom(32),
        owner="finance-dept",
        ttl=86400
    )

    validator = TokenValidator(store)
    return validator, store
